      "id": "DMSR-2803",
      "title": "PSF-Matched Coadds",
      "text": "One (ugrizy plus multi-band) set of PSF-matched coadds shall be made but shall not be archived."
    },
    {
      "id": "DMSR-5774",
      "title": "Detecting faint variable objects",
      "text": "The DMS shall be able to detect faint objects showing long-term variability, or nearby object with high proper motions."
    },
    {
      "id": "DMSR-4892",
      "title": "Targeted Coadds",
      "text": "It shall be possible to retain small sections of all generated coadds."
    },
    {
      "id": "DMSR-6165",
      "title": "Coadd Image Method Constraints",
      "text": "Coadd Images shall be created by combining spatially overlapping Processed Visit Images (on which bad pixels and transient sources have been masked), where the contributing Processed Visit Images have been re-projected to a common reference geometry, and matched to a common background level which best approximates the astrophysical background."
    },
    {
      "id": "DMSR-7937",
      "title": "Provide PSF for Coadded Images",
      "text": "The DMS shall determine a characterization of the PSF for any speciﬁed location in coadded images."
    },
    {
      "id": "DMSR-6393",
      "title": "Coadded Image Provenance",
      "text": "For each Coadded Image, DMS shall store: the list of input images and the pipeline parameters, including software versions, used to derive it, and a suﬃcient set of metadata attributes for users to re-create them in whole or in part."
    },
